(()=>{
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function burst(x,y,count=14){if(reduced.matches)return;for(let i=0;i<count;i++){let p=document.createElement('i'),angle=Math.random()*Math.PI*2,dist=40+Math.random()*100;p.className='rock-spark';p.style.cssText='left:'+x+'px;top:'+y+'px;--dx:'+Math.cos(angle)*dist+'px;--dy:'+(Math.sin(angle)*dist-45)+'px;--turn:'+Math.random()*260+'deg;--life:'+(650+Math.random()*500)+'ms';document.body.append(p);p.addEventListener('animationend',()=>p.remove(),{once:true})}}
function celebrate(){let existing=document.querySelector('.finish-toast');if(existing)existing.remove();let box=document.createElement('section');box.className='finish-toast';box.setAttribute('role','status');box.innerHTML='<button class="close-finish" aria-label="Fermer">×</button><span>🤘</span><strong>DU GRAND ART !</strong><p>Ton dessin est terminé.</p><button class="finish-download">↓ Télécharger mon dessin</button>';document.body.append(box);box.querySelector('.close-finish').onclick=()=>box.remove();box.querySelector('.finish-download').onclick=()=>document.querySelector('#save').click();burst(innerWidth/2,innerHeight*.4,42);document.querySelector('#save')?.classList.add('ready-download')}
window.RockFX={burst,celebrate,reduced};
if(!reduced.matches){let field=document.createElement('div');field.className='embers';field.setAttribute('aria-hidden','true');for(let i=0;i<12;i++){let p=document.createElement('i');p.style.cssText='--x:'+Math.random()*100+'%;--duration:'+(9+Math.random()*10)+'s;--delay:-'+Math.random()*20+'s;--drift:'+(Math.random()*100-50)+'px';field.append(p)}document.body.prepend(field)}
})();
